const e={name:"Isdrakens Skatt",randomEquipment:"Slumpmässig Utrustning",randomItem:"Slumpmässigt Föremål",trapDoor:"Fälla",e1m0:{name:"Trollgrottan"},e1m1:{name:"Maktens Tre Portar",notes:{hint1:"Bortom sten och eld ska du finna De Onda Gruvorna, vägen till Isdrakens skatt.",hint2:"Vattenporten. <Det finns en bild av en havsdrake under texten>",hint3:"Luftporten. <Det finns en bild av en pegasus under texten>",hint4:"Eldporten. <Det finns en bild av en hippogriff under texten>"}},e1m2:{name:"De Onda Gruvorna",notes:{hint1:"Vaktrum",hint2:"Titta i pelarrummet efter dvärgakungens arsenal",hint3:"För att nå Isdrakens skatt, titta bakom spegeln i alkemistens laboratorium.",hint4:"En stor spegel dekorerar den bortre väggen i detta rum."}},e1m3:{name:"Den Fruktansvärda Labyrinten",notes:{hint1:"En pil på den bortre väggen i korridoren pekar åt vänster.",hint2:"En pil på den bortre väggen i korridoren pekar åt höger.",hint3:"Det finns en mosaik i golvet. Den skildrar en orm som virvlar runt en dvärg, samtidigt som den kämpar mot en isdrake. I ormens käftar finns en skattkista.",hint4:"En pil på den bortre väggen i korridoren pekar åt vänster."}},e1m4:{name:"Det Mörka Citadellet",secrets:{note1:"Ödlan går åt höger och framåt. Ormen går åt vänster och framåt.",stair:"En dold trappa, avslöjad av halsbandets ljus."},notes:{liberVortex:"På golvet ligger en bok, Liber Vortex. På dess första sidan står det 'När Järndörren öppnas, gå som Ödlan två steg, sen som Ormen ett steg..'",ironDoor:"Dörren är väldigt tydligt gjord av järn."}},e1m5:{name:"Isdrakens Skatt",notes:{magicNumber:"Tre är det magiska talet, men fyra är Mörkerherrarna",stoneFace:"Ett stenansikte i väggen talar till er: 'Vägen till eldens sal ska återfinnas i den blå mörkerherrens kammare...'",crystalBall:"Ni kikar i kristallkulan och ser en väldig grottsal. I grottan fins en spiralformad stenbro som leder till en flat klippa mitt i den väldiga salen. Mitt på klippan står de fyra mörkerherrarna och förbereder en ondskefull ritual. Ni kan höra deras mullrande röster: 'Bara tre timmar kvar till världens undergång, förbered nedkallandet av vår onde herres förgörelseblixt!' Ni inser att ni genast måste skynda vidare och finna vägen till grottan om ni ska kunna besegra mörkerherrarna."}},e1m6:{name:"Slutstriden"},testingGrounds:{name:"Testområde",secrets:{trapDoor:"Välkommen till Drakriddarna"}}},r={iceDragon:e};export{r as default,e as iceDragon};
